    <script type="module">
        /* 更新进度条辅助函数 */
        function updateProgressBar(barId, valueId, rawValue, min = 0, max = 100, color = null) {
            const numericValue = parseFloat(rawValue);
            if (!isNaN(numericValue)) {
                const clampedValue = _.clamp(numericValue, min, max);
                const percentage = max - min === 0 ? 0 : ((clampedValue - min) / (max - min)) * 100;

                $(`#${valueId}`).text(clampedValue);
                const cssProps = { width: `${percentage}%` };
                if (color) {
                    cssProps.backgroundImage = 'none';
                    cssProps.backgroundColor = color;
                }
                $(`#${barId}`).css(cssProps);
            } else {
                $(`#${valueId}`).text(rawValue);
            }
        }

        /* 填充状态栏数据 */
        function populateCharacterData() {
            try {
                const all_variables = getAllVariables();
                const characterData = all_variables.stat_data;

                if (!characterData) {
                    $('#status-card').html("<div class='error-tip'>无法加载状态数据</div>");
                    return;
                }

                /* Ghost 好感度：范围 0 ~ 100 */
                updateProgressBar(
                    'ghost-affection-bar',
                    'ghost-affection',
                    _.get(characterData, 'Ghost.好感度', 0),
                    0, 100, '#b81c34'
                );

                /* Ghost 性欲值：范围 0 ~ 100 */
                updateProgressBar(
                    'ghost-desire-bar',
                    'ghost-desire',
                    _.get(characterData, 'Ghost.性欲值', 0),
                    0, 100, '#8a1428'
                );

                /* Ghost 戒备值：范围 0 ~ 100 */
                updateProgressBar(
                    'ghost-guard-bar',
                    'ghost-guard',
                    _.get(characterData, 'Ghost.戒备值', 0),
                    0, 100, '#4f6b8f'
                );

                /* 文本类属性 */
                $('#ghost-outfit').text(_.get(characterData, 'Ghost.衣着', 'N/A'));
                $('#ghost-status-badge').text(_.get(characterData, 'Ghost.状态', 'N/A'));
                $('#ghost-inner-voice').text(_.get(characterData, 'Ghost.心声', 'N/A'));
            } catch (error) {
                $('#status-card').html(`<div class='error-tip'>状态栏加载出错: ${error.message}</div>`);
            }
        }

        /* 初始化 */
        async function init() {
            /* 等待 MVU 系统初始化完成 */
            await waitGlobalInitialized('Mvu');

            /* 填充数据 */
            populateCharacterData();
        }

        $(errorCatched(init));
    </script>
